<?php

namespace App\Http\Controllers\Web;

use App\Http\Controllers\Controller;
use Inertia\Inertia;
use Inertia\Response;
use Symfony\Component\HttpFoundation\BinaryFileResponse;

class ApiReferenceController extends Controller
{
    /**
     * The OpenAPI document generated by `php artisan scramble:export`.
     */
    private const SPEC_PATH = 'docs/api/openapi.json';

    public function show(): Response
    {
        return Inertia::render('developers/api-reference', [
            'spec' => json_decode(file_get_contents(base_path(self::SPEC_PATH)), true, flags: JSON_THROW_ON_ERROR),
            'apiBaseUrl' => url('/api'),
            'interactiveDocsUrl' => app()->isLocal() ? url('/docs/api') : null,
        ]);
    }

    public function download(): BinaryFileResponse
    {
        return response()->file(base_path(self::SPEC_PATH), ['Content-Type' => 'application/json']);
    }
}
